export async function checkPublication(state,publication,head,sourceRoot,phase){
 const pointer=await observe(state,phase+':publication.git-pointer',()=>readFile(join(sourceRoot,'.git'),'utf8'));
 assert(pointer==='gitdir: '+publication.gitDirectory+'\n','worktree Git pointer differs');
 const canonical=await observe(state,phase+':publication.git-directory',()=>realpath(publication.gitDirectory));assert(canonical===publication.gitDirectory,'Git directory differs');
 const contents=await observe(state,phase+':publication.HEAD',()=>readFile(join(canonical,'HEAD'),'utf8'));
 if(publication.branch===null)assert(contents===head+'\n','detached published HEAD differs');
 else{
  assert(/^refs\/heads\/[A-Za-z0-9._/-]+$/.test(publication.branch)&&!publication.branch.includes('..'),'branch differs');
  assert(contents==='ref: '+publication.branch+'\n','symbolic published HEAD differs');
  const relative=await observe(state,phase+':publication.commondir',()=>readFile(join(canonical,'commondir'),'utf8'));
  assert(relative===publication.commonRelative+'\n','Git common directory pointer differs');
  const common=await observe(state,phase+':publication.common-realpath',()=>realpath(join(canonical,publication.commonRelative)));assert(common===publication.commonDirectory,'Git common directory differs');
  const ref=await observe(state,phase+':publication.ref',()=>readFile(join(common,publication.branch),'utf8'));assert(ref===head+'\n','published branch commit differs');
 }
 return {head,rootCleanPublication:'Root frozen observation under continuous no-writer lease; parent does not spawn git status'};
}
export async function writeJSON(state,label,path,value){return observe(state,label,()=>writeFile(path,JSON.stringify(value,null,2)+'\n',{flag:'wx',mode:384}));}

